mapper.sql:
LEFT JOIN (
    SELECT ml.mark_id, COUNT(*) AS likeCount
    FROM mark_like ml
    JOIN mark m2 ON m2.id = ml.mark_id AND m2.film_id = #{filmId}
    GROUP BY ml.mark_id
) lc ON lc.mark_id = m.id
LEFT JOIN mark_like viewer_like
       ON viewer_like.mark_id = m.id AND viewer_like.user_id = #{viewerId}
